#pragma once
#include "../../support.hpp"
namespace algs {
template<class V>struct GraphEdge{V from,to;double weight;};template<class V>class Graph{std::vector<V>order;std::map<V,std::vector<std::pair<V,double>>>adjacency;public:const bool directed;explicit Graph(bool d=false):directed(d){}int vertexCount()const{return int(order.size());}int edgeCount()const{return int(edges().size());}Graph&addVertex(V v){if(!hasVertex(v)){adjacency[v]={};order.push_back(v);}return *this;}Graph&addEdge(V f,V t,double w=1){addVertex(f).addVertex(t);auto set=[&](V a,V b){for(auto&e:adjacency[a])if(e.first==b){e.second=w;return;}adjacency[a].emplace_back(b,w);};set(f,t);if(!directed)set(t,f);return *this;}bool removeEdge(V f,V t){auto erase=[&](V a,V b){auto it=adjacency.find(a);if(it==adjacency.end())return false;auto&ns=it->second;for(auto n=ns.begin();n!=ns.end();++n)if(n->first==b){ns.erase(n);return true;}return false;};bool removed=erase(f,t);if(removed&&!directed)erase(t,f);return removed;}bool removeVertex(V v){if(!adjacency.erase(v))return false;order.erase(std::find(order.begin(),order.end(),v));for(auto&[k,ns]:adjacency)ns.erase(std::remove_if(ns.begin(),ns.end(),[&](auto&e){return e.first==v;}),ns.end());return true;}bool hasVertex(V v)const{return adjacency.count(v)!=0;}bool hasEdge(V f,V t)const{return weight(f,t).has_value();}std::optional<double>weight(V f,V t)const{auto it=adjacency.find(f);if(it!=adjacency.end())for(auto&e:it->second)if(e.first==t)return e.second;return {};}std::vector<V>neighbors(V v)const{std::vector<V>r;auto it=adjacency.find(v);if(it!=adjacency.end())for(auto&e:it->second)r.push_back(e.first);return r;}int degree(V v)const{return int(neighbors(v).size());}std::vector<V>vertices()const{return order;}std::vector<GraphEdge<V>>edges()const{std::vector<GraphEdge<V>>r;std::set<V>seen;for(auto&f:order){for(auto&[t,w]:adjacency.at(f))if(directed||!seen.count(t))r.push_back({f,t,w});seen.insert(f);}return r;}struct MatrixResult{std::vector<V>vertices;Matrix matrix;};MatrixResult toAdjacencyMatrix()const{MatrixResult r{order,Matrix(order.size(),Numbers(order.size()))};std::map<V,int>index;for(int i=0;i<int(order.size());++i)index[order[i]]=i;for(auto&f:order)for(auto&[t,w]:adjacency.at(f))r.matrix[index[f]][index[t]]=w;return r;}struct ListResult{std::vector<V>vertices;std::vector<std::vector<int>>list;};ListResult toAdjacencyList()const{ListResult r{order,std::vector<std::vector<int>>(order.size())};std::map<V,int>index;for(int i=0;i<int(order.size());++i)index[order[i]]=i;for(auto&f:order)for(auto&[t,w]:adjacency.at(f))r.list[index[f]].push_back(index[t]);return r;}};
}
